using System;
using System.Linq;
using UnityEngine;
namespace BWVR {
public sealed class StormParticipant:MonoBehaviour {public StormChapter chapter;public bool Pending=>chapter!=null&&chapter.Pending&&chapter.Person==GetComponent<VillagerSocial>();}
// Bounded chapter orchestration; existing actor motors own all movement and carrying.
public sealed partial class StormChapter {
 readonly Func<SliceState> season;readonly CreatureHybrid god;readonly IslandNavigation nav;readonly IslandWeather weather;readonly VillagerRoutine[] jobs;readonly IslandDiscoveries discoveries;
 StormChapterState bound;bool restore;float searchIn;readonly Transform refugeView;readonly Material refugeMaterial;
 public StormChapterState State=>season().StormChapter;
 public VillagerSocial Person{get;private set;}public bool Claimed{get;private set;}
 public bool Pending=>State.Active&&State.opportunity&&!State.resolved&&Person!=null;
 public Transform GatheringPoint=>refugeView;
 public Transform Creature=>god.transform;
 public Vector3 Refuge=>nav.ToWorld(State.refuge);
 public bool CanOffer=>Pending&&!Claimed&&!Person.GetComponent<CarryItem>().held&&!season().paused&&Person.Memory.trust>=.2f&&god.CanSeeCue(Person.GetComponent<HybridTarget>(),false,true);
 public string Description=>State.phase==StormPhase.Dormant?"Exploration":"Gathering Storm · "+State.phase+(State.resolved?" · "+State.source+" assistance":"")+(Supply?.delivered==true?" · timber sheltered":"");
 public StormChapter(Transform parent,CreatureHybrid god,IslandNavigation nav,IslandWeather weather,VillagerRoutine[] jobs,IslandDiscoveries discoveries,Func<SliceState> season){this.god=god;this.nav=nav;this.weather=weather;this.jobs=jobs;this.discoveries=discoveries;this.season=season;refugeMaterial=new Material(Shader.Find("BWVR/GameSurface")){color=new Color(.35f,.85f,.7f),enableInstancing=true};refugeView=new GameObject("Storm gathering point — safe arrival ring").transform;refugeView.SetParent(parent,false);var line=refugeView.gameObject.AddComponent<LineRenderer>();line.useWorldSpace=false;line.loop=true;line.positionCount=40;line.widthMultiplier=nav.Scale*.3f;line.sharedMaterial=refugeMaterial;for(int i=0;i<40;i++){float a=i*Mathf.PI/20;line.SetPosition(i,new Vector3(Mathf.Cos(a)*4,.15f,Mathf.Sin(a)*4)*nav.Scale);}Ensure();}
 void Ensure(){if(bound==State)return;if(bound!=null&&bound.Active)weather.automatic=bound.previousAutomatic;Claimed=false;Person=null;bound=State;restore=bound.opportunity&&!bound.resolved;searchIn=0;if(bound.Active)weather.automatic=false;if(bound.opportunity&&bound.villager>=0){Person=jobs[bound.villager].GetComponent<VillagerSocial>();var marker=Person.GetComponent<StormParticipant>()??Person.gameObject.AddComponent<StormParticipant>();marker.chapter=this;}refugeView.gameObject.SetActive(bound.Active&&bound.opportunity);if(bound.opportunity)refugeView.position=Refuge;BindSupplies();}
 public bool Start(){Ensure();if(State.Active||season().paused||SupplyItem?.held==true||jobs.Any(j=>j.GetComponent<CarryItem>().held))return false;var previous=weather.automatic;season().stormChapter=new StormChapterState{phase=StormPhase.Calm,episode=Math.Min(1000000,State.episode+1),previousAutomatic=previous};Ensure();weather.automatic=false;EnterPhase();return true;}
 void EnterPhase(){weather.automatic=false;var kind=State.phase==StormPhase.Warning?IslandWeatherKind.Wind:State.phase==StormPhase.Storm?IslandWeatherKind.Rain:IslandWeatherKind.Clear;weather.State.Set(kind,State.phase==StormPhase.Complete?90:Mathf.Max(1,StormChapterState.Duration(State.phase)));if(State.phase==StormPhase.Storm)TryOpportunity();if(State.phase==StormPhase.Complete){if(Pending)ReleaseCreature();weather.automatic=State.previousAutomatic;refugeView.gameObject.SetActive(false);}god.Journal.Add(god.State.time,"storm chapter",CreatureAction.IdleOrObserve,"chapter-storm",State.phase.ToString());IslandAudio.Cue(State.phase==StormPhase.Warning?IslandSound.Gust:State.phase==StormPhase.Complete?IslandSound.Discovery:IslandSound.Notice,god.transform.position,86471,.6f);}
 public void Advance(float dt,bool paused){Ensure();SupplyVisibility();if(!State.Active||paused||!HybridState.Number(dt,0,1000000)||dt<=0)return;if(restore){if(nav.TreeNavigationPending)return;restore=false;if(Person!=null){ClearOtherTasks(Person);var walker=Person.GetComponent<IslandNavigator>();if(walker.CanPlace(nav.ToWorld(State.actorPoint),out var at))Person.transform.position=at;else{Debug.LogWarning("BWVR_STORM_RESUME: stored actor point unavailable; retaining current safe position");State.actorPoint=nav.ToNav(Person.transform.position);}}}if(Pending&&State.playerArrivalPending){State.playerArrivalPending=false;Confirm(RescueSource.Player);}
 var before=State.phase;State.Step(dt,false);if(before!=State.phase)EnterPhase();if(State.phase==StormPhase.Storm&&!State.opportunity){searchIn-=dt;if(searchIn<=0){searchIn=2;TryOpportunity();}}if(Pending){State.distress=Mathf.Min(100000000,State.distress+dt);Capture();}AdvanceSupplies(dt);if(State.opportunity){refugeView.position=Refuge;refugeView.gameObject.SetActive(State.Active);}}
 bool TryOpportunity(){if(State.opportunity||nav.TreeNavigationPending)return false;var choices=jobs.Select((job,i)=>new{job,i}).Where(p=>!p.job.GetComponent<CarryItem>().held&&p.job.GetComponent<VillagerSocial>().Memory.injury<=0).OrderBy(p=>(p.job.transform.position-god.transform.position).sqrMagnitude);foreach(var choice in choices){var person=choice.job.GetComponent<VillagerSocial>();var walker=person.GetComponent<IslandNavigator>();for(int k=0;k<16;k++){var wanted=person.transform.position+Quaternion.Euler(0,k*22.5f,0)*Vector3.forward*nav.Scale*30;if(!walker.CanPlace(wanted,out var safe)||!discoveries.Reachable(person.transform.position,safe,walker.profile)||!god.CanReach(safe))continue;State.opportunity=true;State.villager=choice.i;State.refuge=nav.ToNav(safe);State.actorPoint=nav.ToNav(person.transform.position);State.frightAt=god.State.time;Person=person;var participant=person.GetComponent<StormParticipant>()??person.gameObject.AddComponent<StormParticipant>();participant.chapter=this;ClearOtherTasks(person);person.Memory.frights=Math.Min(1000000,person.Memory.frights+1);person.Memory.lastFrightAt=State.frightAt;refugeView.position=safe;refugeView.gameObject.SetActive(true);person.GetComponent<HumanoidMotion>()?.Signal(true,true,safe);IslandAudio.Cue(IslandSound.Uneasy,person.transform.position,person.GetEntityId().GetHashCode(),.65f);god.Journal.Add(god.State.time,"storm assistance opportunity",CreatureAction.SocialInteraction,person.GetComponent<HybridTarget>().id,"Frightened villager seeks a safe gathering point");return true;}}return false;}
 void ClearOtherTasks(VillagerSocial person){var job=person.GetComponent<VillagerRoutine>();god.GetComponentInParent<QuestSlice>().GetComponentInChildren<VillageFamilies>()?.Release(job);god.GetComponentInParent<QuestSlice>().GetComponentInChildren<VillageCathedral>()?.Cancel(job);person.GetComponent<VillagerResourceGathering>()?.Cancel();person.ResetTask();person.GetComponent<VillagerExploration>()?.ResetTask();person.GetComponent<VillagerBlockPlay>()?.ResetTask();job.BeginHandsFreeActivity();}
 public bool TickVillager(VillagerRoutine job,float dt){if(!Pending||job.GetComponent<VillagerSocial>()!=Person)return false;if(Claimed||job.GetComponent<CarryItem>().held)return true;var explore=job.GetComponent<VillagerExploration>();if(!explore.StormEvacuating)explore.TryStormEvacuation(this);explore.Tick(dt,false);return true;}
 public bool ClaimCreature(){if(!CanOffer)return false;ClearOtherTasks(Person);Claimed=true;return true;}
 public void ReleaseCreature(){Claimed=false;}
 public bool AtSafety=>Person!=null&&Vector3.Distance(Person.transform.position,Refuge)<nav.Scale*4&&Person.GetComponent<CarryItem>().held==false;
 public bool Confirm(RescueSource by){if(!Pending||season().paused||!AtSafety||by==RescueSource.Creature&&!Claimed||!State.Resolve(by))return false;State.playerArrivalPending=false;State.actorPoint=nav.ToNav(Person.transform.position);if(by!=RescueSource.Creature&&god.State.guidance.status==GuidanceStatus.Active&&god.State.guidance.target==Person.GetComponent<HybridTarget>().id)god.CancelGuidance("Villager already reached safety");if(Mathf.Abs(Person.Memory.lastFrightAt-State.frightAt)<.01f)Person.Memory.lastFrightAt=Mathf.Max(-100,god.State.time-90);if(by==RescueSource.Creature){Person.Memory.trust=Mathf.Clamp01(Person.Memory.trust+.06f);Person.Memory.affinity=Mathf.Clamp01(Person.Memory.affinity+.04f);god.State.RememberBond(Person.GetComponent<HybridTarget>().id,true);}Person.GetComponent<VillagerExploration>().ResetTask();Person.GetComponent<HumanoidMotion>()?.React();Person.GetComponent<VillagerAffect>()?.Reassured();Claimed=false;god.Journal.Add(god.State.time,"storm safe arrival",CreatureAction.SocialInteraction,Person.GetComponent<HybridTarget>().id,by.ToString());IslandAudio.Cue(IslandSound.Content,Refuge,Person.GetEntityId().GetHashCode(),.7f);return true;}
 public void PlayerPicked(CarryItem item){Ensure();SupplyPicked(item);if(!Pending||item.GetComponent<VillagerSocial>()!=Person)return;State.playerArrivalPending=false;Capture();if(Claimed)god.Interrupt("Player took over storm assistance");Person.GetComponent<VillagerExploration>().ResetTask();}
 public void PlayerPlaced(CarryItem item){Ensure();SupplyPlaced(item);if(Pending&&item.GetComponent<VillagerSocial>()==Person){Capture();if(season().paused&&AtSafety)State.playerArrivalPending=true;else Confirm(RescueSource.Player);}}
 public bool Stop(){Ensure();if(!State.Active)return false;if(Claimed||SupplyClaimed)god.Interrupt("Storm chapter ended by player");Person?.GetComponent<VillagerExploration>().ResetTask();State.phase=StormPhase.Stopped;State.elapsed=0;State.playerArrivalPending=false;Claimed=false;weather.State.Set(IslandWeatherKind.Clear,90);weather.automatic=State.previousAutomatic;refugeView.gameObject.SetActive(false);god.Journal.Add(god.State.time,"storm chapter stopped",CreatureAction.IdleOrObserve,"chapter-storm","Returned to free play; learning retained");return true;}
 public void Capture(){CaptureSupplies();if(Pending&&Person.GetComponent<CarryItem>().held==false)State.actorPoint=nav.ToNav(Person.transform.position);}
 public void Dispose(){DisposeSupplies();if(refugeView!=null)UnityEngine.Object.Destroy(refugeView.gameObject);if(refugeMaterial!=null)UnityEngine.Object.Destroy(refugeMaterial);}
}
}
